// ClientWithResponsesInterface is the interface specification for the client with responses above.
type ClientWithResponsesInterface interface {

	// ListSspiUpgradeStepsWithResponse List available pre-checks and upgrade step definitions
	//
	// Retrieves the list of all pre-checks and upgrade step definitions.
	// This endpoint provides visibility into the upgrade workflow phases and
	// pre-checks validations that will be executed, enabling the UI to display
	// the upgrade process to the user before execution.
	//
	// The steps are listed in the order they will be executed during the upgrade
	// process. This endpoint returns step definitions only, not execution status.
	// To retrieve execution status and progress, use GET /upgrade/status.
	//
	// Returns a wrapper object for the known response body format(s).
	//
	// Corresponds with GET /sspi/upgrade (the `ListSspiUpgradeSteps` operationId).
	ListSspiUpgradeStepsWithResponse(ctx context.Context, reqEditors ...RequestEditorFn) (*ListSspiUpgradeStepsResponse, error)

	// TriggerSspiUpgradeWithResponse Execute appliance upgrade operation
	//
	// Executes the appliance upgrade operation to transition the system to the target
	// version based on the specified action. This asynchronous operation
	// orchestrates the complete upgrade workflow including management cluster,
	// workload clusters, and appliance VM.
	//
	// Supported actions:
	//
	// PRECHECKS_ONLY: Runs only pre-upgrade validation checks without performing
	// the upgrade. This operation is idempotent and non-disruptive; it can be
	// safely run on a live production system to assess readiness before a
	// maintenance window. PRECHECKS_ONLY is only allowed when the upgrade
	// status is NOT_STARTED. Only one pre-checks operation can run at a time.
	//
	// START: Runs pre-checks followed by the full upgrade. This is the standard
	// upgrade flow. START is only allowed when the upgrade status is
	// NOT_STARTED. Requires a scheduled maintenance window as the appliance VM will
	// reboot during the upgrade, causing temporary unavailability of the
	// management interface. Ensure a backup is taken before initiating. Do not
	// interrupt the upgrade process once initiated unless absolutely necessary
	// for emergency recovery.
	//
	// CONTINUE: Starts the upgrade without running pre-checks. CONTINUE is
	// only allowed when the upgrade status is NOT_STARTED and pre-checks
	// have completed successfully, returns an error for any other state.
	//
	// RETRY: Resumes the upgrade workflow from the failed step. Already
	// completed upgrade steps are skipped automatically. RETRY is only
	// allowed when the upgrade status is FAILED, which means pre-checks
	// have already passed. If pre-checks failed, use START again.
	//
	// Prerequisites:
	// - Upgrade Manager must be upgraded to target version
	//   (POST /upgrade/manager?action=upgrade)
	// - A valid upgrade package must be available
	//
	// Recommended workflow:
	//
	// 1. Check versions (GET /upgrade/version-summary), review packages
	//    (GET /upgrade/packages), and upgrade the Upgrade Manager
	//    (POST /upgrade/manager).
	// 2. Run pre-checks (POST /upgrade?action=PRECHECKS_ONLY) and review
	//    results (GET /upgrade/status).
	// 3. During a maintenance window, start the upgrade
	//    (POST /upgrade?action=START or POST /upgrade?action=CONTINUE if
	//    pre-checks already passed), and monitor progress
	//    (GET /upgrade/status).
	// 4. If upgrade fails, address the issue and retry
	//    (POST /upgrade?action=RETRY).
	// 5. Review upgrade history (GET /upgrade/history) after completion.
	//
	// Returns a wrapper object for the known response body format(s).
	//
	// Corresponds with POST /sspi/upgrade (the `TriggerSspiUpgrade` operationId).
	TriggerSspiUpgradeWithResponse(ctx context.Context, params *TriggerSspiUpgradeParams, reqEditors ...RequestEditorFn) (*TriggerSspiUpgradeResponse, error)

	// GetSspiUpgradeHistoryWithResponse Retrieve upgrade history
	//
	// Retrieves the upgrade history of the system.
	//
	// The list is sorted in descending order by start time, with the most recent
	// upgrade first. The history includes the current upgrade if one is in progress.
	//
	// Note: Upgrade Manager upgrades are not included in this history. Only
	// full appliance upgrades (initiated by the user) are tracked.
	//
	// Returns a wrapper object for the known response body format(s).
	//
	// Corresponds with GET /sspi/upgrade/history (the `GetSspiUpgradeHistory` operationId).
	GetSspiUpgradeHistoryWithResponse(ctx context.Context, reqEditors ...RequestEditorFn) (*GetSspiUpgradeHistoryResponse, error)

	// ListUpgradeManagerStepsWithResponse List Upgrade Manager upgrade step definitions
	//
	// Retrieves the list of all Upgrade Manager upgrade step definitions. This
	// endpoint returns metadata about each step in the Upgrade Manager upgrade
	// process, enabling the UI to display the steps to the user.
	//
	// The Upgrade Manager is the service that orchestrates appliance upgrades. It
	// must be upgraded to the target version before the main appliance upgrade can
	// proceed.
	//
	// The Upgrade Manager upgrade is typically quick and involves updating the
	// upgrade service binary and UI components.
	//
	// This endpoint returns step definitions only, not execution status. To
	// retrieve execution status and progress, use GET /upgrade/manager/status.
	//
	// Returns a wrapper object for the known response body format(s).
	//
	// Corresponds with GET /sspi/upgrade/manager (the `ListUpgradeManagerSteps` operationId).
	ListUpgradeManagerStepsWithResponse(ctx context.Context, reqEditors ...RequestEditorFn) (*ListUpgradeManagerStepsResponse, error)

	// TriggerUpgradeManagerUpgradeWithBodyWithResponse Execute Upgrade Manager upgrade operation
	//
	// Upgrades the Upgrade Manager service itself to the target version specified
	// in the request body. This is distinct from POST /upgrade which upgrades
	// the entire appliance - this endpoint only upgrades the upgrade
	// orchestration tool.
	//
	// The Upgrade Manager must be at the target version before it can
	// orchestrate the main appliance upgrade (POST /upgrade).
	//
	// Prerequisites:
	// - A valid upgrade package must be uploaded to the system
	// - No other upgrade operation should be in progress
	//
	// The operation executes asynchronously and returns immediately with a status
	// URL. Use GET /upgrade/manager/status to monitor upgrade progress.
	//
	// Only one Upgrade Manager upgrade operation can execute at a time (returns
	// 409 if upgrade is in progress or already completed).
	//
	// If the upgrade fails, this endpoint can be called again to retry the upgrade.
	//
	// Takes any type of body and a specified content type, and returns a wrapper object for the known response body format(s).
	//
	// Corresponds with POST /sspi/upgrade/manager (the `TriggerUpgradeManagerUpgrade` operationId).
	TriggerUpgradeManagerUpgradeWithBodyWithResponse(ctx context.Context, params *TriggerUpgradeManagerUpgradeParams, contentType string, body io.Reader, reqEditors ...RequestEditorFn) (*TriggerUpgradeManagerUpgradeResponse, error)

	// TriggerUpgradeManagerUpgradeWithResponse Execute Upgrade Manager upgrade operation
	//
	// Upgrades the Upgrade Manager service itself to the target version specified
	// in the request body. This is distinct from POST /upgrade which upgrades
	// the entire appliance - this endpoint only upgrades the upgrade
	// orchestration tool.
	//
	// The Upgrade Manager must be at the target version before it can
	// orchestrate the main appliance upgrade (POST /upgrade).
	//
	// Prerequisites:
	// - A valid upgrade package must be uploaded to the system
	// - No other upgrade operation should be in progress
	//
	// The operation executes asynchronously and returns immediately with a status
	// URL. Use GET /upgrade/manager/status to monitor upgrade progress.
	//
	// Only one Upgrade Manager upgrade operation can execute at a time (returns
	// 409 if upgrade is in progress or already completed).
	//
	// If the upgrade fails, this endpoint can be called again to retry the upgrade.
	//
	// Takes a body of the `application/json` content type, and returns a wrapper object for the known response body format(s).
	//
	// Corresponds with POST /sspi/upgrade/manager (the `TriggerUpgradeManagerUpgrade` operationId).
	TriggerUpgradeManagerUpgradeWithResponse(ctx context.Context, params *TriggerUpgradeManagerUpgradeParams, body TriggerUpgradeManagerUpgradeJSONRequestBody, reqEditors ...RequestEditorFn) (*TriggerUpgradeManagerUpgradeResponse, error)

	// GetUpgradeManagerStatusWithResponse Retrieve Upgrade Manager upgrade status and progress
	//
	// Retrieves real-time status and detailed progress information for the
	// Upgrade Manager upgrade operation. This endpoint provides visibility into
	// upgrade execution with granular reporting for each upgrade step and an
	// overall progress percentage.
	//
	// Poll this endpoint at regular intervals while upgrade is in progress.
	//
	// Upon completion, verify that overall_status is SUCCESS before proceeding
	// with appliance upgrade (POST /upgrade). If status is FAILED,
	// examine the upgrade_steps array for the failed step to identify root cause.
	//
	// If no Upgrade Manager upgrade has been initiated, the response indicates
	// NOT_STARTED status with progress_percentage of 0.
	//
	// Returns a wrapper object for the known response body format(s).
	//
	// Corresponds with GET /sspi/upgrade/manager/status (the `GetUpgradeManagerStatus` operationId).
	GetUpgradeManagerStatusWithResponse(ctx context.Context, reqEditors ...RequestEditorFn) (*GetUpgradeManagerStatusResponse, error)

	// GetUpgradePackagesWithResponse Retrieve available upgrade packages
	//
	// Retrieves the list of available upgrade packages from the depot service
	// and returns the packages eligible for the upgrade after evaluating
	// each available package.
	//
	// The response includes package version, name, and size for each available
	// upgrade bundle that has been uploaded to the system.
	//
	// Only packages eligible for the upgrade are returned.
	//
	// Returns a wrapper object for the known response body format(s).
	//
	// Corresponds with GET /sspi/upgrade/packages (the `GetUpgradePackages` operationId).
	GetUpgradePackagesWithResponse(ctx context.Context, reqEditors ...RequestEditorFn) (*GetUpgradePackagesResponse, error)

	// GetSspiUpgradeStatusWithResponse Retrieve upgrade operation status and progress
	//
	// Retrieves real-time status and detailed progress information for the
	// upgrade operation. This endpoint provides visibility into upgrade
	// execution with granular reporting for each upgrade phase.
	//
	// Poll this endpoint at regular intervals while upgrade is in progress.
	//
	// Upon completion, verify that overall_status is SUCCESS. If status is FAILED,
	// examine the upgrade_steps array for the failed step to identify root cause
	// or connect with VMware Support for assistance.
	//
	// If no upgrade has been initiated, the response indicates NOT_STARTED status.
	//
	// Note: During the appliance VM upgrade phase, the system will reboot and this
	// endpoint may be temporarily unavailable. Resume polling after the system
	// comes back online.
	//
	// Returns a wrapper object for the known response body format(s).
	//
	// Corresponds with GET /sspi/upgrade/status (the `GetSspiUpgradeStatus` operationId).
	GetSspiUpgradeStatusWithResponse(ctx context.Context, reqEditors ...RequestEditorFn) (*GetSspiUpgradeStatusResponse, error)

	// GetVersionSummaryWithResponse Retrieve version summary
	//
	// Retrieves the current versions of appliance components and the target upgrade
	// version. The current version reflects the actually installed version on
	// the appliance. After a successful upgrade (e.g., 5.1.1 to 5.2.0), the
	// current version updates to the new version (5.2.0).
	//
	// The response includes:
	// - Current appliance version
	// - Current Upgrade Manager version
	// - Target appliance version (set when upgrade is initiated)
	//
	// Returns a wrapper object for the known response body format(s).
	//
	// Corresponds with GET /sspi/upgrade/version-summary (the `GetVersionSummary` operationId).
	GetVersionSummaryWithResponse(ctx context.Context, reqEditors ...RequestEditorFn) (*GetVersionSummaryResponse, error)
}

