// TriggerSspiUpgradeWithResponse Execute appliance upgrade operation
//
// Executes the appliance upgrade operation to transition the system to the target
// version based on the specified action. This asynchronous operation
// orchestrates the complete upgrade workflow including management cluster,
// workload clusters, and appliance VM.
//
// Supported actions:
//
// PRECHECKS_ONLY: Runs only pre-upgrade validation checks without performing
// the upgrade. This operation is idempotent and non-disruptive; it can be
// safely run on a live production system to assess readiness before a
// maintenance window. PRECHECKS_ONLY is only allowed when the upgrade
// status is NOT_STARTED. Only one pre-checks operation can run at a time.
//
// START: Runs pre-checks followed by the full upgrade. This is the standard
// upgrade flow. START is only allowed when the upgrade status is
// NOT_STARTED. Requires a scheduled maintenance window as the appliance VM will
// reboot during the upgrade, causing temporary unavailability of the
// management interface. Ensure a backup is taken before initiating. Do not
// interrupt the upgrade process once initiated unless absolutely necessary
// for emergency recovery.
//
// CONTINUE: Starts the upgrade without running pre-checks. CONTINUE is
// only allowed when the upgrade status is NOT_STARTED and pre-checks
// have completed successfully, returns an error for any other state.
//
// RETRY: Resumes the upgrade workflow from the failed step. Already
// completed upgrade steps are skipped automatically. RETRY is only
// allowed when the upgrade status is FAILED, which means pre-checks
// have already passed. If pre-checks failed, use START again.
//
// Prerequisites:
//   - Upgrade Manager must be upgraded to target version
//     (POST /upgrade/manager?action=upgrade)
//   - A valid upgrade package must be available
//
// Recommended workflow:
//
//  1. Check versions (GET /upgrade/version-summary), review packages
//     (GET /upgrade/packages), and upgrade the Upgrade Manager
//     (POST /upgrade/manager).
//  2. Run pre-checks (POST /upgrade?action=PRECHECKS_ONLY) and review
//     results (GET /upgrade/status).
//  3. During a maintenance window, start the upgrade
//     (POST /upgrade?action=START or POST /upgrade?action=CONTINUE if
//     pre-checks already passed), and monitor progress
//     (GET /upgrade/status).
//  4. If upgrade fails, address the issue and retry
//     (POST /upgrade?action=RETRY).
//  5. Review upgrade history (GET /upgrade/history) after completion.
//
// Returns a wrapper object for the known response body format(s).
//
// Corresponds with POST /sspi/upgrade (the `TriggerSspiUpgrade` operationId).
func (c *ClientWithResponses) TriggerSspiUpgradeWithResponse(ctx context.Context, params *TriggerSspiUpgradeParams, reqEditors ...RequestEditorFn) (*TriggerSspiUpgradeResponse, error) {
	rsp, err := c.TriggerSspiUpgrade(ctx, params, reqEditors...)
	if err != nil {
		return nil, err
	}
	return ParseTriggerSspiUpgradeResponse(rsp)
}

